  `mime_type` varchar(128) DEFAULT '' COMMENT 'MIME类型',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_mind_map_id` (`mind_map_id`)
